"""Shared read-only spatial indexes over map blockers and ground loot.

- `BlockerIndex` buckets a map's blockers by cell. `los` gives exactly the same answer as
  `geometry.line_of_sight(..., map.blockers)` but tests only the blockers in cells the segment
  crosses. `blocker_index(map)` caches one index per `MapDefinition`; combat, bot perception and
  navigation, and `maps.is_open_point` all use it.
- `LootIndex` buckets ground loot by cell and picks up newly placed loot incrementally.
  `loot_index(match)` keeps one per match (views and bots share it). It is released by
  `clear_match(match)` or automatically when the match object is garbage collected.
"""

import math
import weakref

from solo_engine.geometry import segment_hits_rect
from solo_engine.model import GroundLoot, MapDefinition, Rect, SoloMatch

_BLOCKER_CELL = 16.0
_LOOT_CELL = 20.0


# --------------------------------------------------------------------------- blockers


def _clip_entry(ax: float, ay: float, bx: float, by: float, rect: Rect) -> float | None:
    """Entry parameter t in 0..1 where segment a->b first touches rect, or None."""
    dx = bx - ax
    dy = by - ay
    t0, t1 = 0.0, 1.0
    for p, q in ((-dx, ax - rect.min_x), (dx, rect.max_x - ax), (-dy, ay - rect.min_y), (dy, rect.max_y - ay)):
        if abs(p) < 1e-12:
            if q < 0:
                return None
            continue
        r = q / p
        if p < 0:
            if r > t1:
                return None
            t0 = max(t0, r)
        else:
            if r < t0:
                return None
            t1 = min(t1, r)
    return t0 if t0 <= t1 else None


class BlockerIndex:
    """Map blockers bucketed by grid cell. Every blocker is listed in each cell it overlaps."""

    def __init__(self, rects: tuple[Rect, ...], cell: float = _BLOCKER_CELL) -> None:
        self.rects = rects
        self.cell = cell
        self.cells: dict[tuple[int, int], list[int]] = {}
        for i, r in enumerate(rects):
            for cx in range(math.floor(r.min_x / cell), math.floor(r.max_x / cell) + 1):
                for cy in range(math.floor(r.min_y / cell), math.floor(r.max_y / cell) + 1):
                    self.cells.setdefault((cx, cy), []).append(i)

    def _candidates(self, ax: float, ay: float, bx: float, by: float) -> set[int]:
        """Indexes of blockers in every cell the segment passes through (a superset of hits)."""
        cells = self.cells
        found: set[int] = set()
        if not cells:
            return found
        c = self.cell
        x0, x1 = (ax, bx) if ax <= bx else (bx, ax)
        dx = bx - ax
        dy = by - ay
        for cx in range(math.floor(x0 / c), math.floor(x1 / c) + 1):
            if abs(dx) < 1e-12:
                ylo, yhi = (ay, by) if ay <= by else (by, ay)
            else:
                lo = max(x0, cx * c)
                hi = min(x1, (cx + 1) * c)
                ya = ay + dy * (lo - ax) / dx
                yb = ay + dy * (hi - ax) / dx
                ylo, yhi = (ya, yb) if ya <= yb else (yb, ya)
            for cy in range(math.floor((ylo - 1e-6) / c), math.floor((yhi + 1e-6) / c) + 1):
                bucket = cells.get((cx, cy))
                if bucket:
                    found.update(bucket)
        return found

    def los(self, ax: float, ay: float, bx: float, by: float) -> bool:
        """Same result as geometry.line_of_sight against the indexed blockers."""
        rects = self.rects
        for i in self._candidates(ax, ay, bx, by):
            if segment_hits_rect(ax, ay, bx, by, rects[i]):
                return False
        return True

    def first_hit(self, ax: float, ay: float, bx: float, by: float) -> Rect | None:
        """The blocker the segment a->b enters first, or None when the segment is clear."""
        best: Rect | None = None
        best_t = math.inf
        for i in sorted(self._candidates(ax, ay, bx, by)):
            t = _clip_entry(ax, ay, bx, by, self.rects[i])
            if t is not None and t < best_t:
                best, best_t = self.rects[i], t
        return best

    def contains(self, x: float, y: float) -> bool:
        """Same result as geometry.inside_any(x, y, rects)."""
        bucket = self.cells.get((math.floor(x / self.cell), math.floor(y / self.cell)))
        if not bucket:
            return False
        return any(self.rects[i].contains(x, y) for i in bucket)

    def near(self, x: float, y: float, radius: float) -> list[Rect]:
        """Blockers in cells overlapping the square around (x, y), in index order."""
        c = self.cell
        found: set[int] = set()
        for cx in range(math.floor((x - radius) / c), math.floor((x + radius) / c) + 1):
            for cy in range(math.floor((y - radius) / c), math.floor((y + radius) / c) + 1):
                bucket = self.cells.get((cx, cy))
                if bucket:
                    found.update(bucket)
        return [self.rects[i] for i in sorted(found)]


_BLOCKER_INDEXES: dict[int, tuple[MapDefinition, BlockerIndex]] = {}


def blocker_index(game_map: MapDefinition) -> BlockerIndex:
    """Cached index for a map. Shipped maps are module constants, so the cache stays small.

    The entry keeps a reference to its map, so an id is never reused while it is cached.
    """
    entry = _BLOCKER_INDEXES.get(id(game_map))
    if entry is not None and entry[0] is game_map:
        return entry[1]
    if len(_BLOCKER_INDEXES) > 64:
        _BLOCKER_INDEXES.clear()
    index = BlockerIndex(tuple(game_map.blockers))
    _BLOCKER_INDEXES[id(game_map)] = (game_map, index)
    return index


# --------------------------------------------------------------------------- loot


class LootIndex:
    """Ground loot ids by cell. Loot never moves; removed loot is skipped lazily on query."""

    def __init__(self, cell: float = _LOOT_CELL) -> None:
        self.cell = cell
        self.cells: dict[tuple[int, int], list[str]] = {}
        self.known: set[str] = set()

    def refresh(self, match: SoloMatch) -> None:
        """Index loot placed since the last refresh. New loot is always appended to match.loot."""
        if not match.loot:
            return
        fresh: list[GroundLoot] = []
        for loot_id in reversed(match.loot):
            if loot_id in self.known:
                break
            fresh.append(match.loot[loot_id])
        c = self.cell
        for g in fresh:
            self.known.add(g.loot_id)
            self.cells.setdefault((math.floor(g.x / c), math.floor(g.y / c)), []).append(g.loot_id)

    def near(self, match: SoloMatch, x: float, y: float, radius: float) -> list[GroundLoot]:
        """Loot within `radius` metres of (x, y), ordered by loot id for determinism."""
        self.refresh(match)
        c = self.cell
        r2 = radius * radius
        loot = match.loot
        found: list[GroundLoot] = []
        for cx in range(math.floor((x - radius) / c), math.floor((x + radius) / c) + 1):
            for cy in range(math.floor((y - radius) / c), math.floor((y + radius) / c) + 1):
                bucket = self.cells.get((cx, cy))
                if not bucket:
                    continue
                alive_ids = []
                for loot_id in bucket:
                    g = loot.get(loot_id)
                    if g is None:
                        continue
                    alive_ids.append(loot_id)
                    if (g.x - x) ** 2 + (g.y - y) ** 2 <= r2:
                        found.append(g)
                if len(alive_ids) != len(bucket):
                    bucket[:] = alive_ids
        found.sort(key=lambda g: g.loot_id)
        return found


_LOOT_INDEXES: dict[int, LootIndex] = {}


def loot_index(match: SoloMatch) -> LootIndex:
    """The shared loot index for one match, released when the match object is collected."""
    key = id(match)
    index = _LOOT_INDEXES.get(key)
    if index is None:
        index = LootIndex()
        _LOOT_INDEXES[key] = index
        weakref.finalize(match, _LOOT_INDEXES.pop, key, None)
    return index


def clear_match(match: SoloMatch) -> None:
    """Drop the loot index for a removed match now (collection does it too)."""
    _LOOT_INDEXES.pop(id(match), None)
